// Validates a gateway request and turns it into a single read-only Xero call.
// Anything not on these allowlists is rejected before Xero is contacted.
const TENANTS = {
  '0a290129-b001-4bfb-903d-d27a8ac55738': 'Hinkley Homes Management',
  '3ae8a283-c7e0-4287-9bcd-4c2561295890': 'Hinkley Homes Holdings',
  '47f65b32-d0d7-4417-bb5c-89ff2d93651e': 'Lettings',
  '4c807578-e0a7-49ad-9644-8e705aec0c2a': 'Hinkley Homes Stays Ltd',
  '9d1fee42-4203-47d8-87aa-6fa8e8ac0fef': 'Hinkley Homes Ltd',
};
const PAGED = ['where', 'order', 'page', 'pageSize'];
const RESOURCES = {
  organisation: { path: 'Organisation', query: [] },
  accounts: { path: 'Accounts', query: ['where', 'order'] },
  trackingCategories: { path: 'TrackingCategories', query: ['where', 'order', 'includeArchived'] },
  contacts: { path: 'Contacts', byId: true, query: [...PAGED, 'IDs', 'includeArchived', 'summaryOnly', 'searchTerm'] },
  // Bills are invoices with where=Type=="ACCPAY".
  invoices: { path: 'Invoices', byId: true, query: [...PAGED, 'IDs', 'InvoiceNumbers', 'ContactIDs', 'Statuses', 'summaryOnly', 'searchTerm'] },
  // Shareable "view and pay" link for one sales invoice (id required).
  onlineInvoice: { path: 'Invoices', byId: true, idRequired: true, suffix: '/OnlineInvoice', query: [] },
  // Sent / reminder / payment events on one invoice (id required).
  invoiceHistory: { path: 'Invoices', byId: true, idRequired: true, suffix: '/History', query: [] },
  // Whether Xero's own automatic invoice reminders are switched on.
  invoiceReminderSettings: { path: 'InvoiceReminders/Settings', query: [] },
  creditNotes: { path: 'CreditNotes', byId: true, query: PAGED },
  payments: { path: 'Payments', byId: true, query: PAGED },
  bankTransactions: { path: 'BankTransactions', byId: true, query: PAGED },
  // Reports need Xero's accounting.reports.read scope, so they go through the
  // "Xero reports" credential (see the "Report?" node); everything else uses "Xero account".
  profitAndLoss: { path: 'Reports/ProfitAndLoss', report: true, query: ['fromDate', 'toDate', 'periods', 'timeframe', 'trackingCategoryID', 'standardLayout', 'paymentsOnly'] },
  balanceSheet: { path: 'Reports/BalanceSheet', report: true, query: ['date', 'periods', 'timeframe', 'trackingOptionID1', 'standardLayout', 'paymentsOnly'] },
  agedPayables: { path: 'Reports/AgedPayablesByContact', report: true, query: ['contactId', 'date', 'fromDate', 'toDate'] },
  // Balance, money in and money out for every bank account over the period.
  bankSummary: { path: 'Reports/BankSummary', report: true, query: ['fromDate', 'toDate'] },
};
const GUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const fail = (status, error) => [{ json: { ok: false, status, error } }];
const body = $input.first().json.body;
if (!body || typeof body !== 'object' || Array.isArray(body)) return fail(400, 'Send a JSON object body.');

const tenantId = String(body.tenantId ?? '').toLowerCase();
if (!TENANTS[tenantId]) return fail(400, 'Unknown tenantId.');

const resource = String(body.resource ?? '');
const spec = Object.hasOwn(RESOURCES, resource) ? RESOURCES[resource] : undefined;
if (!spec) return fail(400, `Unknown resource. Allowed: ${Object.keys(RESOURCES).join(', ')}.`);

let path = spec.path;
if (body.id !== undefined && body.id !== null && body.id !== '') {
  if (!spec.byId) return fail(400, `${resource} does not take an id.`);
  if (!GUID.test(String(body.id))) return fail(400, 'id must be a Xero GUID.');
  path += `/${String(body.id).toLowerCase()}`;
}
if (spec.idRequired && path === spec.path) return fail(400, `${resource} needs an id.`);
if (spec.suffix) path += spec.suffix;

const query = {};
const rawQuery = body.query ?? {};
if (typeof rawQuery !== 'object' || Array.isArray(rawQuery)) return fail(400, 'query must be an object.');
for (const [key, value] of Object.entries(rawQuery)) {
  if (!spec.query.includes(key)) return fail(400, `Query parameter "${key}" is not allowed for ${resource}.`);
  if (value === null || typeof value === 'object') return fail(400, `Query parameter "${key}" must be a string, number or boolean.`);
  query[key] = String(value);
}
if (query.pageSize !== undefined) {
  const size = Number(query.pageSize);
  if (!Number.isInteger(size) || size < 1 || size > 1000) return fail(400, 'pageSize must be a whole number from 1 to 1000.');
}

const headers = { 'xero-tenant-id': tenantId, Accept: 'application/json' };
if (body.ifModifiedSince !== undefined && body.ifModifiedSince !== null && body.ifModifiedSince !== '') {
  const since = new Date(String(body.ifModifiedSince));
  if (Number.isNaN(since.getTime())) return fail(400, 'ifModifiedSince must be an ISO-8601 date-time.');
  headers['If-Modified-Since'] = since.toUTCString();
}

return [{ json: { ok: true, report: spec.report === true, tenantId, tenantName: TENANTS[tenantId], resource, path, query, headers } }];
